using Relay.Core.Calendar;
using Relay.Core.Normality;
using Relay.Core.Queries;
using Relay.Core.Tests.TestDoubles;

namespace Relay.Core.Tests.Normality;

public sealed class WeeklyGridBuilderTests
{
    private const string SelectedWeekStart = "2026-03-16";

    private static readonly WeekWindow SelectedWeek = TestTime.UtcMidnightWeek(SelectedWeekStart);
    private static readonly IReadOnlyList<WeekWindow> BaselineWindows = TestTime.UtcMidnightBaselineBefore(SelectedWeekStart, 8);

    private readonly WeeklyGridBuilder _weeklyGridBuilder = new();

    private static SiteFirstActivity SiteFirstSeen(string location, string firstActivityUtc) =>
        new(location, TestTime.Utc(firstActivityUtc));

    private static WeeklySiteCount CountFor(string location, string weekStart, int count) =>
        new(location, TestTime.Day(weekStart), count);

    private static WeeklySeries SeriesFor(IReadOnlyList<LocationSeries> locationSeries, string location) =>
        locationSeries.Single(series => series.Location == location).Series;

    [Fact]
    public void BuildLocationSeriesSiteWithNoEventsInSelectedWeekAppearsWithZeroCount()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-01-05T10:00:00Z") };
        var weeklySiteCounts = BaselineWindows
            .Select(window => new WeeklySiteCount("Site A", window.WeekStart, 2))
            .ToList();

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        var siteSeries = SeriesFor(locationSeries, "Site A");
        siteSeries.SelectedWeekCount.ShouldBe(0);
        siteSeries.EligibleWeekCounts.ShouldBe([2, 2, 2, 2, 2, 2, 2, 2]);
    }

    [Fact]
    public void BuildLocationSeriesSiteSilentForWholeBaselineIsZeroFilledNotDropped()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-01-05T10:00:00Z") };
        var weeklySiteCounts = new[] { CountFor("Site A", SelectedWeekStart, 4) };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        var siteSeries = SeriesFor(locationSeries, "Site A");
        siteSeries.SelectedWeekCount.ShouldBe(4);
        siteSeries.EligibleWeekCounts.ShouldBe([0, 0, 0, 0, 0, 0, 0, 0]);
    }

    [Fact]
    public void BuildLocationSeriesWeeksOnOrBeforeFirstActivityWeekAreIneligible()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-02-10T09:00:00Z") };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-02-09", 1),
            CountFor("Site A", "2026-02-16", 2),
            CountFor("Site A", "2026-02-23", 3),
            CountFor("Site A", "2026-03-02", 4),
            CountFor("Site A", "2026-03-09", 5),
        };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([2, 3, 4, 5], ignoreOrder: true);
    }

    [Fact]
    public void BuildLocationSeriesFirstActivityExactlyAtWindowStartMakesThatWeekIneligible()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-02-09T00:00:00Z") };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-02-09", 1),
            CountFor("Site A", "2026-02-16", 2),
            CountFor("Site A", "2026-02-23", 3),
            CountFor("Site A", "2026-03-02", 4),
            CountFor("Site A", "2026-03-09", 5),
        };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([2, 3, 4, 5], ignoreOrder: true);
    }

    [Fact]
    public void BuildLocationSeriesFirstActivityOneSecondBeforeWindowStartMakesThatWeekEligible()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-02-08T23:59:59Z") };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-02-02", 7),
            CountFor("Site A", "2026-02-09", 1),
            CountFor("Site A", "2026-02-16", 2),
            CountFor("Site A", "2026-02-23", 3),
            CountFor("Site A", "2026-03-02", 4),
            CountFor("Site A", "2026-03-09", 5),
        };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([1, 2, 3, 4, 5], ignoreOrder: true);
    }

    [Fact]
    public void BuildLocationSeriesFirstActivityInsideOldestBaselineWeekLeavesSevenEligibleWeeks()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-01-20T10:00:00Z") };
        var weeklySiteCounts = new[] { CountFor("Site A", "2026-01-19", 9) };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([0, 0, 0, 0, 0, 0, 0]);
    }

    [Fact]
    public void BuildLocationSeriesFirstActivityInWeekBeforeOldestBaselineWeekLeavesAllEightEligible()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-01-18T23:00:00Z") };
        var weeklySiteCounts = new[] { CountFor("Site A", "2026-01-19", 9) };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([9, 0, 0, 0, 0, 0, 0, 0], ignoreOrder: true);
    }

    [Fact]
    public void BuildLocationSeriesSiteFirstSeenInsideSelectedWeekIsListedWithNoEligibleWeeks()
    {
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-03-22T23:59:59Z") };
        var weeklySiteCounts = new[] { CountFor("Site A", SelectedWeekStart, 1) };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        var siteSeries = SeriesFor(locationSeries, "Site A");
        siteSeries.SelectedWeekCount.ShouldBe(1);
        siteSeries.EligibleWeekCounts.ShouldBeEmpty();
    }

    [Theory]
    [InlineData("2026-03-23T00:00:00Z")]
    [InlineData("2026-04-06T12:00:00Z")]
    public void BuildLocationSeriesSiteFirstSeenOnOrAfterSelectedWeekEndIsExcluded(string firstActivityUtc)
    {
        var siteFirstActivities = new[]
        {
            SiteFirstSeen("Site A", "2026-01-05T10:00:00Z"),
            SiteFirstSeen("Site B", firstActivityUtc),
        };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, []);

        locationSeries.Select(series => series.Location).ShouldBe(["Site A"]);
    }

    [Fact]
    public void BuildLocationSeriesEachSiteUsesItsOwnFirstActivityForEligibility()
    {
        var siteFirstActivities = new[]
        {
            SiteFirstSeen("Site A", "2026-01-05T10:00:00Z"),
            SiteFirstSeen("Site B", "2026-02-24T10:00:00Z"),
        };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-02-23", 6),
            CountFor("Site B", "2026-02-23", 1),
            CountFor("Site B", "2026-03-02", 3),
            CountFor("Site B", "2026-03-09", 4),
            CountFor("Site B", SelectedWeekStart, 5),
        };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        locationSeries.Select(series => series.Location).ShouldBe(["Site A", "Site B"], ignoreOrder: true);
        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([0, 0, 0, 0, 0, 6, 0, 0], ignoreOrder: true);
        SeriesFor(locationSeries, "Site B").EligibleWeekCounts.ShouldBe([3, 4], ignoreOrder: true);
        SeriesFor(locationSeries, "Site B").SelectedWeekCount.ShouldBe(5);
    }

    [Fact]
    public void BuildLocationSeriesDstWindowsDecideEligibilityByUtcWindowStartNotUtcMidnight()
    {
        var chicagoSelectedWeek = new WeekWindow(TestTime.Day("2026-03-16"), TestTime.Utc("2026-03-16T05:00:00Z"), TestTime.Utc("2026-03-23T05:00:00Z"));
        var chicagoBaselineWindows = new[]
        {
            new WeekWindow(TestTime.Day("2026-03-02"), TestTime.Utc("2026-03-02T06:00:00Z"), TestTime.Utc("2026-03-09T05:00:00Z")),
            new WeekWindow(TestTime.Day("2026-03-09"), TestTime.Utc("2026-03-09T05:00:00Z"), TestTime.Utc("2026-03-16T05:00:00Z")),
        };
        var siteFirstActivities = new[] { SiteFirstSeen("Site A", "2026-03-09T04:30:00Z") };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-03-02", 1),
            CountFor("Site A", "2026-03-09", 6),
        };

        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(chicagoSelectedWeek, chicagoBaselineWindows, siteFirstActivities, weeklySiteCounts);

        SeriesFor(locationSeries, "Site A").EligibleWeekCounts.ShouldBe([6]);
    }

    [Fact]
    public void BuildLocationSeriesNoSitesReturnsEmptyList()
    {
        var locationSeries = _weeklyGridBuilder.BuildLocationSeries(SelectedWeek, BaselineWindows, [], []);

        locationSeries.ShouldBeEmpty();
    }

    [Fact]
    public void BuildAccountSeriesSumsSitesPerWeekAndZeroFillsSilentWeeks()
    {
        var siteFirstActivities = new[]
        {
            SiteFirstSeen("Site A", "2026-01-05T10:00:00Z"),
            SiteFirstSeen("Site B", "2026-01-06T10:00:00Z"),
        };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-01-19", 2),
            CountFor("Site B", "2026-01-19", 3),
            CountFor("Site A", "2026-02-02", 4),
            CountFor("Site B", "2026-03-09", 1),
            CountFor("Site A", SelectedWeekStart, 7),
            CountFor("Site B", SelectedWeekStart, 8),
        };

        var accountSeries = _weeklyGridBuilder.BuildAccountSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        accountSeries.SelectedWeekCount.ShouldBe(15);
        accountSeries.EligibleWeekCounts.ShouldBe([5, 0, 4, 0, 0, 0, 0, 1], ignoreOrder: true);
    }

    [Fact]
    public void BuildAccountSeriesUsesEarliestSiteFirstActivityAndDropsIneligibleWeeksInsteadOfZeroFilling()
    {
        var siteFirstActivities = new[]
        {
            SiteFirstSeen("Site A", "2026-02-24T10:00:00Z"),
            SiteFirstSeen("Site B", "2026-02-10T10:00:00Z"),
        };
        var weeklySiteCounts = new[]
        {
            CountFor("Site B", "2026-02-09", 9),
            CountFor("Site B", "2026-02-16", 2),
            CountFor("Site B", "2026-02-23", 3),
            CountFor("Site B", "2026-03-02", 4),
            CountFor("Site B", "2026-03-09", 5),
        };

        var accountSeries = _weeklyGridBuilder.BuildAccountSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        accountSeries.EligibleWeekCounts.ShouldBe([2, 3, 4, 5], ignoreOrder: true);
    }

    [Fact]
    public void BuildAccountSeriesIncludesCountsFromWeeksThatAreIneligibleForTheSiteItself()
    {
        var siteFirstActivities = new[]
        {
            SiteFirstSeen("Site A", "2026-01-05T10:00:00Z"),
            SiteFirstSeen("Site B", "2026-02-24T10:00:00Z"),
        };
        var weeklySiteCounts = new[]
        {
            CountFor("Site A", "2026-02-23", 6),
            CountFor("Site B", "2026-02-23", 1),
        };

        var accountSeries = _weeklyGridBuilder.BuildAccountSeries(SelectedWeek, BaselineWindows, siteFirstActivities, weeklySiteCounts);

        accountSeries.EligibleWeekCounts.ShouldBe([0, 0, 0, 0, 0, 7, 0, 0], ignoreOrder: true);
    }

    [Fact]
    public void BuildAccountSeriesNoSitesReturnsZeroCountAndNoEligibleWeeks()
    {
        var accountSeries = _weeklyGridBuilder.BuildAccountSeries(SelectedWeek, BaselineWindows, [], []);

        accountSeries.SelectedWeekCount.ShouldBe(0);
        accountSeries.EligibleWeekCounts.ShouldBeEmpty();
    }
}
using Relay.Core.Normality;

namespace Relay.Core.Tests.Normality;

public sealed class LocationRankerTests
{
    private static readonly Baseline SufficientBaseline = new(8, 5.0, 2, 10);

    private readonly LocationRanker _locationRanker = new();

    private static LocationHealth Evaluated(string location, HealthStatus status, double deviation) =>
        new(location, 5, SufficientBaseline, status, deviation);

    private static LocationHealth Insufficient(string location, int weeksUsed) =>
        new(location, 5, new Baseline(weeksUsed, null, null, null), HealthStatus.InsufficientData, null);

    private List<string> RankedNames(params LocationHealth[] locations) =>
        _locationRanker.Rank(locations).Select(location => location.Location).ToList();

    [Fact]
    public void RankInsufficientDataRowsGoLastSortedByName()
    {
        var rankedNames = RankedNames(
            Insufficient("Site C", 3),
            Evaluated("Site Z", HealthStatus.Normal, 0.0),
            Insufficient("Site A", 0),
            Evaluated("Site Y", HealthStatus.Above, 2.5));

        rankedNames.ShouldBe(["Site Y", "Site Z", "Site A", "Site C"]);
    }

    [Fact]
    public void RankFlaggedRowsGoBeforeNormalRowsWithLargerDeviation()
    {
        var rankedNames = RankedNames(
            Evaluated("Site A", HealthStatus.Normal, -1.86),
            Evaluated("Site B", HealthStatus.Above, 1.83));

        rankedNames.ShouldBe(["Site B", "Site A"]);
    }

    [Fact]
    public void RankAboveAndBelowRowsAreOrderedTogetherByAbsoluteDeviationDescending()
    {
        var rankedNames = RankedNames(
            Evaluated("Site A", HealthStatus.Above, 2.11),
            Evaluated("Site B", HealthStatus.Below, -3.19),
            Evaluated("Site C", HealthStatus.Above, 2.81));

        rankedNames.ShouldBe(["Site B", "Site C", "Site A"]);
    }

    [Fact]
    public void RankUsesUnroundedDeviationWhenRoundedValuesTie()
    {
        var rankedNames = RankedNames(
            Evaluated("Site A", HealthStatus.Normal, 1.296),
            Evaluated("Site B", HealthStatus.Normal, 1.304));

        rankedNames.ShouldBe(["Site B", "Site A"]);
    }

    [Fact]
    public void RankEqualAbsoluteDeviationPutsBelowBeforeAboveThenName()
    {
        var rankedNames = RankedNames(
            Evaluated("Site B", HealthStatus.Above, 2.5),
            Evaluated("Site A", HealthStatus.Above, 2.5),
            Evaluated("Site C", HealthStatus.Below, -2.5));

        rankedNames.ShouldBe(["Site C", "Site A", "Site B"]);
    }

    [Fact]
    public void RankNormalRowsWithOppositeSignsAndEqualMagnitudeAreOrderedByName()
    {
        var rankedNames = RankedNames(
            Evaluated("Site B", HealthStatus.Normal, -0.5),
            Evaluated("Site A", HealthStatus.Normal, 0.5));

        rankedNames.ShouldBe(["Site A", "Site B"]);
    }

    [Fact]
    public void RankNameTieBreakIsOrdinalSoUppercaseSortsBeforeLowercase()
    {
        var rankedNames = RankedNames(
            Evaluated("site a", HealthStatus.Normal, 0.0),
            Evaluated("Site B", HealthStatus.Normal, 0.0));

        rankedNames.ShouldBe(["Site B", "site a"]);
    }

    [Fact]
    public void RankInsufficientDataNameOrderIsOrdinal()
    {
        var rankedNames = RankedNames(
            Insufficient("site a", 2),
            Insufficient("Site B", 2));

        rankedNames.ShouldBe(["Site B", "site a"]);
    }

    [Fact]
    public void RankAccount14July20OrdersBelowFirstThenNormalRowsByAbsoluteDeviation()
    {
        var rankedNames = RankedNames(
            Evaluated("Site A", HealthStatus.Normal, 0.61),
            Evaluated("Site D", HealthStatus.Normal, -0.19),
            Evaluated("Site C", HealthStatus.Normal, 0.98),
            Evaluated("Site B", HealthStatus.Below, -2.16));

        rankedNames.ShouldBe(["Site B", "Site C", "Site A", "Site D"]);
    }

    [Fact]
    public void RankAccount14AppointmentTiesAtZeroDeviationAreOrderedByName()
    {
        var rankedNames = RankedNames(
            Evaluated("Site D", HealthStatus.Normal, 0.0),
            Evaluated("Site C", HealthStatus.Normal, 0.0),
            Evaluated("Site B", HealthStatus.Normal, 0.0),
            Evaluated("Site A", HealthStatus.Normal, -1.12));

        rankedNames.ShouldBe(["Site A", "Site B", "Site C", "Site D"]);
    }

    [Fact]
    public void RankAccount14March2PutsFlaggedThenNormalThenInsufficientByName()
    {
        var rankedNames = RankedNames(
            Insufficient("Site C", 3),
            Evaluated("Site B", HealthStatus.Normal, 1.49),
            Insufficient("Site A", 3),
            Evaluated("Site D", HealthStatus.Above, 3.25));

        rankedNames.ShouldBe(["Site D", "Site B", "Site A", "Site C"]);
    }

    [Fact]
    public void RankIsIndependentOfInputOrder()
    {
        var locations = new[]
        {
            Evaluated("Site A", HealthStatus.Normal, 0.0),
            Evaluated("Site B", HealthStatus.Normal, 0.0),
            Evaluated("Site C", HealthStatus.Below, -2.5),
            Evaluated("Site D", HealthStatus.Above, 2.5),
            Insufficient("Site E", 1),
            Insufficient("Site F", 1),
        };

        var rankedForward = RankedNames(locations);
        var rankedReversed = RankedNames(locations.Reverse().ToArray());

        rankedForward.ShouldBe(["Site C", "Site D", "Site A", "Site B", "Site E", "Site F"]);
        rankedReversed.ShouldBe(rankedForward);
    }

    [Fact]
    public void RankKeepsEveryLocationWithItsValuesUnchanged()
    {
        var belowLocation = new LocationHealth("Site G", 0, new Baseline(8, 5.5, 2, 9), HealthStatus.Below, -3.19);
        var insufficientLocation = Insufficient("Site N", 2);

        var ranked = _locationRanker.Rank([insufficientLocation, belowLocation]);

        ranked.Count.ShouldBe(2);
        ranked[0].ShouldBe(belowLocation);
        ranked[1].ShouldBe(insufficientLocation);
    }

    [Fact]
    public void RankEmptyListReturnsEmptyList()
    {
        var ranked = _locationRanker.Rank([]);

        ranked.ShouldBeEmpty();
    }
}

