    [Theory]
    [InlineData("2026-03-23T00:00:00Z")]
    [InlineData("2026-04-06T12:00:00Z")]
    public void BuildLocationSeriesSiteFirstSeenOnOrAfterSelectedWeekEndIsExcluded(string firstActivityUtc)
