            FROM sys.indexes
            WHERE object_id = OBJECT_ID(N'dbo.activity_events')
              AND is_unique = 1
              AND is_primary_key = 0
            """).ToListAsync(CancellationToken);

        uniqueNonPrimaryIndexCounts.ShouldBe([0]);
    }
}

