        report.Root.GetProperty("minimumEligibleWeeks").GetInt32().ShouldBe(4);
    }

    private static List<string> PropertyNames(JsonElement jsonObject) =>
        [.. jsonObject.EnumerateObject().Select(property => property.Name)];
}

