    [InlineData("2026-03-23T00:00:00Z", new[] { "Site A" })]
    public void BuildLocationSeriesListsOnlySitesFirstSeenBeforeSelectedWeekEnd(string siteBFirstActivityUtc, string[] expectedLocations)
    {
